 for(std::string native:{"native","native_ramps","native_identity_v2"})for(std::string display:{"led-lcd-srgb","led-lcd-wcg","oled"})for(unsigned b=0;b<5;++b){unsigned w=widths[b];auto r=readRow(cpu/native/(display+"_1_band"+std::to_string(b+1)+".f64"),w),t=readRow(cpu/native/(display+"_2_band"+std::to_string(b+1)+".f64"),w),expected=readRow(cpu/native/(display+"_quality_band"+std::to_string(b+1)+"_self.f64"),w);auto result=gpu.mutual(r,t,w,w);compare(result,expected);std::ofstream f(out/(native+"_"+display+"_band"+std::to_string(b+1)+".f64"),std::ios::binary);f.write(reinterpret_cast<const char*>(result.data()),result.size()*8);}
 const size_t nativeWords=words;for(unsigned seed=0;seed<3;++seed)for(unsigned b=0;b<5;++b){unsigned w=widths[b];std::vector<double> r(w*w),t(w*w);for(size_t i=0;i<r.size();++i){r[i]=seed==0?(i%19==0?1.:0.):seed==1?(i%2?-1.:1.)*double((i+b)%97)*.013:(i%7==0?1e6:-1e-12);t[i]=seed==0?(i%17==0?.7:0.):seed==1?double((i+5)%71)*.009:(i%5==0?-1e5:1e-11);}auto result=gpu.mutual(r,t,w,w),expected=mutual_mask_double(r,t,w,w);compare(result,expected);}
